from click.testing import CliRunner
from click.core import ParameterSource

@click.command()
@click.option('--upper', 'transformation', flag_value='upper', default='lower')
def cli(transformation):
    click.echo(f"transformation={transformation}")

@click.command()
@click.option('--upper', 'transformation', flag_value='upper', default='lower', envvar='UPPER')
def cli2(transformation):
    click.echo(f"transformation={transformation}")

for env in ({}, {'UPPER': '1'}, {'TRANSFORMATION': '1'}):
    r = CliRunner().invoke(cli, [], env=env)
    print("no-envvar-decl env=%s -> %r" % (env, r.output))
for env in ({}, {'UPPER': '1'}):
    r = CliRunner().invoke(cli2, [], env=env)
    print("envvar='UPPER' env=%s -> %r" % (env, r.output))

# parameter source
ctx = click.Context(cli)
with ctx:
    p = cli.params[0]
    print("source for transformation:", p.consume_value(ctx, {})[1])
    print("get_default:", repr(p.get_default(ctx)), "declared default:", repr(p.default))
EOF
